		    packet[0] == 0xff && packet[1] == JPEG_MARKER_SOI &&
		    buf->bytesused != 0) {
			buf->state = UVC_BUF_STATE_READY;
			buf->error = 1;
			stream->last_fid ^= UVC_STREAM_FID;
			return -EAGAIN;
		}
	}

	stream->last_fid = fid;

	return header_len;
}

